===== AssignHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Create-owner step: stamps the new owner with its {@link Household} identifier, computed
 * deterministically from its own last name and postcode. Every owner sharing a last name and
 * postcode therefore resolves to the same {@code householdId} without any owner-to-owner
 * linking. A household is keyed on the postcode, so an owner without one has no household and
 * is left unstamped.
 *
 * <p>Runs after {@link BuildOwner} and before {@link EnsureUniqueIdentity}, so the household
 * identifier is in place for the duplicate check that keys off it.
 */
public class AssignHousehold {

    public void service(@Val Owner owner) {
        String postcode = owner.getPostcode();
        if (postcode == null || postcode.isBlank()) {
            return;
        }
        owner.setHouseholdId(Household.id(owner.getLastName(), postcode));
    }
}
===== EnsureUniqueIdentity =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;

/**
 * Create-owner step: the duplicate block. Two owners are the same person when they share the
 * same {@link IdentityKey} (normalized telephone, email and household), so a request whose key
 * already belongs to an existing owner is rejected with a 409. Additional members of the same
 * {@link Household} with a distinct identity (a different telephone or email) are <em>not</em>
 * duplicates and are admitted; {@code sharesHousehold} still bypasses the block explicitly.
 *
 * <p>Runs after {@link AssignHousehold} (so the new owner already carries its final
 * {@code householdId}, part of its identity key) and before {@link FlagPossibleDuplicate} and
 * {@link SaveOwner}.
 */
public class EnsureUniqueIdentity {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return; // declared household member bypasses the duplicate block
        }
        if (owner.getHouseholdId() == null) {
            return; // no postcode -> no household -> nothing to collide with
        }
        String identityKey = IdentityKey.of(owner);
        for (Owner existing : ownerRepository.findAll()) {
            if (existing.isDeleted()) {
                continue; // a soft-deleted owner no longer occupies its identity
            }
            if (identityKey.equals(IdentityKey.of(existing))) {
                throw new DuplicateIdentityException(identityKey);
            }
        }
    }
}
===== FlagPossibleDuplicate =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Step of {@code POST /api/owners}: records whether the new owner is a possible duplicate of
 * an existing one — sharing the same last name and postcode but a different telephone (see
 * {@link PossibleDuplicate}). Such an owner is still created; the matching owner's id is
 * stored in {@code possibleDuplicateOf} so a later read can flag it.
 *
 * <p>Runs after {@link EnsureUniqueIdentity} has already rejected exact-identity duplicates, so
 * a match reaching here is a distinct additional household member — either a declared one
 * ({@code sharesHousehold}) or one admitted by its different telephone. A declared member is
 * not a suspected duplicate, so it is never flagged; otherwise the earliest-created (lowest id)
 * matching owner is recorded, and no match leaves the field unset.
 */
public class FlagPossibleDuplicate {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            owner.setPossibleDuplicateOf(null); // a declared household member is not a suspected duplicate
            return;
        }
        Integer matchId = null;
        for (Owner existing : ownerRepository.findAll()) {
            if (existing.isDeleted()) {
                continue; // a soft-deleted owner is not a duplicate to flag against
            }
            if (PossibleDuplicate.matches(existing, owner)) {
                Integer id = existing.getId();
                if (id != null && (matchId == null || id < matchId)) {
                    matchId = id;
                }
            }
        }
        owner.setPossibleDuplicateOf(matchId);
    }
}

