===== IdentityKey =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The single definition of an owner's <em>identity key</em>: the value that decides when
 * two owners are the same person. It joins the owner's normalized telephone, email and
 * household identifier into one string, so a duplicate is an exact match of the whole key
 * rather than of any single field.
 *
 * <p>Key = {@code normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty)}.
 * All three parts are already stored in canonical form ({@link NormalizeOwnerTelephone}
 * stores the E.164 telephone, {@link NormalizeOwnerEmail} the lower-cased email and
 * {@link AssignHousehold} the deterministic household id), so the key is built from the
 * owner's stored fields; email is lower-cased defensively so the comparison is
 * case-insensitive.
 *
 * <p>Exposed as a derived, read-only owner field and used by the create endpoint's duplicate
 * block (see {@link EnsureUniqueIdentity}): two owners collide only when their whole keys
 * match, so additional household members with a different telephone or email are admitted.
 */
public final class IdentityKey {

    private IdentityKey() {
    }

    /** The identity key of an existing owner, derived from its stored fields. */
    public static String of(Owner owner) {
        return of(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
    }

    /** The identity key for the given normalized telephone, email and household id. */
    public static String of(String telephone, String email, String householdId) {
        return part(telephone) + "|" + lowerCased(email) + "|" + part(householdId);
    }

    /** A field value, or the empty string when absent. */
    private static String part(String value) {
        return value == null ? "" : value;
    }

    /** An email lower-cased, or the empty string when absent. */
    private static String lowerCased(String email) {
        return email == null ? "" : email.toLowerCase(Locale.ROOT);
    }
}
===== Household =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.OptionalInt;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The single definition of an owner "household": owners sharing the same last name and
 * postcode. The last name is compared case-insensitively with runs of whitespace collapsed
 * to a single space; the postcode is taken as stored. Provides the deterministic identifier
 * shared by the household.
 *
 * <p>The identifier is derived deterministically from the normalized last name and postcode
 * — the first 12 upper-case hex characters of SHA-256 over {@code normalizedLastName + '|' +
 * postcode} — so every owner with the same last name and postcode resolves to the same value
 * regardless of creation order, and no owner-to-owner linking is needed.
 *
 * @see AssignHousehold stamps each owner with its computed identifier.
 * @see EnsureUniqueIdentity blocks a second owner in the same household unless it opts in.
 */
final class Household {

    /** Length of the household identifier, in hex characters. */
    private static final int ID_LENGTH = 12;

    private Household() {
    }

    /** The stable identifier shared by every owner in the household keyed by {@code lastName}
     *  and {@code postcode}. */
    static String id(String lastName, String postcode) {
        String key = normalizeName(lastName) + "|" + (postcode == null ? "" : postcode);
        return Sha256.hex(key, ID_LENGTH);
    }

    /** How many of the given owners belong to the household with {@code householdId}. Owners with a
     *  null or non-matching {@code householdId} are not counted; a null {@code householdId} yields 0. */
    static long size(String householdId, Iterable<Owner> owners) {
        if (householdId == null) {
            return 0;
        }
        long count = 0;
        for (Owner owner : owners) {
            if (householdId.equals(owner.getHouseholdId())) {
                count++;
            }
        }
        return count;
    }

    /** The highest {@code membershipLevel} among owners in the household with {@code householdId},
     *  or empty when it has no such member. Owners with a null or non-matching {@code householdId},
     *  or with no level yet, are ignored; a null {@code householdId} yields empty. */
    static OptionalInt maxMembershipLevel(String householdId, Iterable<Owner> owners) {
        if (householdId == null) {
            return OptionalInt.empty();
        }
        OptionalInt max = OptionalInt.empty();
        for (Owner owner : owners) {
            Integer level = owner.getMembershipLevel();
            if (householdId.equals(owner.getHouseholdId()) && level != null
                    && (max.isEmpty() || level > max.getAsInt())) {
                max = OptionalInt.of(level);
            }
        }
        return max;
    }

    /** A last name trimmed and lower-cased, with internal whitespace runs collapsed to a single space. */
    private static String normalizeName(String value) {
        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}
===== PossibleDuplicate =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The single definition of an owner "possible duplicate": a softer match than the hard
 * {@link IdentityKey}. A new owner possibly duplicates an existing one when they share the
 * same last name (compared case-insensitively) and the same postcode but have
 * <em>different</em> telephones — enough overlap to look like the same person, yet distinct
 * enough that {@link EnsureUniqueIdentity} did not treat it as a hard duplicate.
 *
 * <p>The postcode must be present on both sides: two owners with no postcode do not share
 * one, so they are not flagged.
 *
 * @see FlagPossibleDuplicate records the matching owner at registration.
 */
final class PossibleDuplicate {

    private PossibleDuplicate() {
    }

    /** Whether {@code existing} is a possible duplicate of the new {@code candidate}. */
    static boolean matches(Owner existing, Owner candidate) {
        return sameLastName(existing, candidate)
                && samePostcode(existing, candidate)
                && differentTelephone(existing, candidate);
    }

    private static boolean sameLastName(Owner existing, Owner candidate) {
        return normalize(existing.getLastName()).equals(normalize(candidate.getLastName()));
    }

    private static boolean samePostcode(Owner existing, Owner candidate) {
        String postcode = candidate.getPostcode();
        return postcode != null && !postcode.isBlank() && postcode.equals(existing.getPostcode());
    }

    private static boolean differentTelephone(Owner existing, Owner candidate) {
        return !normalize(candidate.getTelephone()).equals(normalize(existing.getTelephone()));
    }

    /** A value trimmed and lower-cased, so comparison is case-insensitive. */
    private static String normalize(String value) {
        return value == null ? "" : value.strip().toLowerCase(Locale.ROOT);
    }
}
