6	/**
7	 * Create-owner step: stamps the new owner with its {@link Household} identifier, computed
8	 * deterministically from its own last name and postcode. Every owner sharing a last name and
9	 * postcode therefore resolves to the same {@code householdId} without any owner-to-owner
10	 * linking. A household is keyed on the postcode, so an owner without one has no household and
11	 * is left unstamped.
12	 *
13	 * <p>Runs after {@link BuildOwner} and before {@link EnsureUniqueIdentity}, so the household
14	 * identifier is in place for the duplicate check that keys off it.
15	 */
16	public class AssignHousehold {
17	
18	    public void service(@Val Owner owner) {
19	        String postcode = owner.getPostcode();
20	        if (postcode == null || postcode.isBlank()) {
21	            return;
22	        }
23	        owner.setHouseholdId(Household.id(owner.getLastName(), postcode));
24	    }
25	}
