2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Step of {@code POST /api/owners}: records whether the new owner is a possible duplicate of
10	 * an existing one — sharing the same last name and postcode but a different telephone (see
11	 * {@link PossibleDuplicate}). Such an owner is still created; the matching owner's id is
12	 * stored in {@code possibleDuplicateOf} so a later read can flag it.
13	 *
14	 * <p>Runs after {@link EnsureUniqueIdentity} has already rejected exact-identity duplicates, so
15	 * a match reaching here is a distinct additional household member — either a declared one
16	 * ({@code sharesHousehold}) or one admitted by its different telephone. A declared member is
17	 * not a suspected duplicate, so it is never flagged; otherwise the earliest-created (lowest id)
18	 * matching owner is recorded, and no match leaves the field unset.
19	 */
20	public class FlagPossibleDuplicate {
21	
22	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
23	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
24	            owner.setPossibleDuplicateOf(null); // a declared household member is not a suspected duplicate
25	            return;
26	        }
27	        Integer matchId = null;
28	        for (Owner existing : ownerRepository.findAll()) {
29	            if (existing.isDeleted()) {
30	                continue; // a soft-deleted owner is not a duplicate to flag against
31	            }
32	            if (PossibleDuplicate.matches(existing, owner)) {
33	                Integer id = existing.getId();
34	                if (id != null && (matchId == null || id < matchId)) {
35	                    matchId = id;
36	                }
37	            }
38	        }
39	        owner.setPossibleDuplicateOf(matchId);
40	    }
41	}
