2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * The single definition of an owner "possible duplicate": a softer match than the hard
9	 * {@link IdentityKey}. A new owner possibly duplicates an existing one when they share the
10	 * same last name (compared case-insensitively) and the same postcode but have
11	 * <em>different</em> telephones — enough overlap to look like the same person, yet distinct
12	 * enough that {@link EnsureUniqueIdentity} did not treat it as a hard duplicate.
13	 *
14	 * <p>The postcode must be present on both sides: two owners with no postcode do not share
15	 * one, so they are not flagged.
16	 *
17	 * @see FlagPossibleDuplicate records the matching owner at registration.
18	 */
19	final class PossibleDuplicate {
20	
21	    private PossibleDuplicate() {
22	    }
23	
24	    /** Whether {@code existing} is a possible duplicate of the new {@code candidate}. */
25	    static boolean matches(Owner existing, Owner candidate) {
26	        return sameLastName(existing, candidate)
27	                && samePostcode(existing, candidate)
28	                && differentTelephone(existing, candidate);
29	    }
30	
31	    private static boolean sameLastName(Owner existing, Owner candidate) {
32	        return normalize(existing.getLastName()).equals(normalize(candidate.getLastName()));
33	    }
34	
35	    private static boolean samePostcode(Owner existing, Owner candidate) {
36	        String postcode = candidate.getPostcode();
37	        return postcode != null && !postcode.isBlank() && postcode.equals(existing.getPostcode());
38	    }
39	
40	    private static boolean differentTelephone(Owner existing, Owner candidate) {
41	        return !normalize(candidate.getTelephone()).equals(normalize(existing.getTelephone()));
42	    }
43	
44	    /** A value trimmed and lower-cased, so comparison is case-insensitive. */
45	    private static String normalize(String value) {
46	        return value == null ? "" : value.strip().toLowerCase(Locale.ROOT);
47	    }
48	}
