6	/**
7	 * The single definition of the disposable email-domain blocklist: addresses whose domain is a
8	 * known throwaway provider are not accepted for an owner. Lookup only; a pure function of the
9	 * email address.
10	 */
11	public final class DisposableEmailDomains {
12	
13	    private static final Set<String> BLOCKED =
14	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
15	
16	    private DisposableEmailDomains() {
17	    }
18	
19	    /** Whether {@code email}'s domain is on the disposable-domain blocklist. */
20	    public static boolean isBlocked(String email) {
21	        if (email == null) {
22	            return false;
23	        }
24	        int at = email.lastIndexOf('@');
25	        if (at < 0) {
26	            return false;
27	        }
28	        String domain = email.substring(at + 1).trim().toLowerCase(Locale.ROOT);
29	        return BLOCKED.contains(domain);
30	    }
31	}
