4	import java.util.regex.Pattern;
5	
6	/**
7	 * The single definition of a valid owner postcode: a 4-digit code that, when the owner's
8	 * city has a known region (see {@link Locality}), must fall within that region's fixed
9	 * inclusive range. Cities with no known region accept any well-formed 4-digit postcode.
10	 *
11	 * <p>Lookup only; pure functions of the postcode and city.
12	 */
13	public final class Postcode {
14	
15	    /** Region -> inclusive 4-digit postcode range {low, high}. */
16	    private static final Map<String, int[]> REGION_RANGE =
17	            Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099},
18	                    "QLD", new int[] {4000, 4099});
19	
20	    private static final Pattern FOUR_DIGITS = Pattern.compile("[0-9]{4}");
21	
22	    private Postcode() {
23	    }
24	
25	    /** Whether {@code postcode} is a well-formed 4-digit code. */
26	    public static boolean isWellFormed(String postcode) {
27	        return postcode != null && FOUR_DIGITS.matcher(postcode).matches();
28	    }
29	
30	    /** Whether a well-formed 4-digit {@code postcode} is permitted for {@code city}: within the
31	     *  city's region range, or anything when the city has no known region. */
32	    public static boolean isInRegion(String city, String postcode) {
33	        int[] range = REGION_RANGE.get(Locality.region(city));
34	        if (range == null) {
35	            return true;
36	        }
37	        int value = Integer.parseInt(postcode);
38	        return value >= range[0] && value <= range[1];
39	    }
40	
41	    /** The region whose fixed range contains {@code postcode}, or {@code null} when the postcode
42	     *  is absent, malformed, or falls in no known range. */
43	    public static String region(String postcode) {
44	        if (!isWellFormed(postcode)) {
45	            return null;
46	        }
47	        int value = Integer.parseInt(postcode);
48	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
49	            int[] range = entry.getValue();
50	            if (value >= range[0] && value <= range[1]) {
51	                return entry.getKey();
52	            }
53	        }
54	        return null;
55	    }
56	}
